#!/bin/bash

# Joel PDF Builder - CONSOLIDATED 2026 EDITION
# = preface + orientation (overview / position / order of revelation)
#   + 10 chapters of Joel in five volumes (one part divider per step of the spine)
#   + 卷末 (systematic reception, to Pentecost and Revelation) + appendices + afterword
# Sources from books/bible/joel/ (老弟兄 methodology + Calvin + Matthew Henry + four Church Fathers +
# Morgan + MacArthur where he speaks of Joel; CUV + NASB 1995 scripture, generated by
# scripts/gen-joel-scripture.py, never typed).
# Modeled on scripts/build-jude-consolidated.sh and scripts/build-daniel-consolidated.sh
# (unnumbered front/back matter so the ten chapters number 1..10; part dividers carry the spine:
# 「啟示的次序·第N步」 + 貫穿的線 table). Cover/back cover follow the Gospel of John / Revelation
# convention via templates/pdf/joel.latex (derived from joel.latex by .sources/tmpl/make-joel-latex.py).

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
INPUT_DIR="$PROJECT_ROOT/books/bible/joel"
STUDY_FILE="$INPUT_DIR/elder-wong-systematic-study.md"
OUTPUT_DIR="$PROJECT_ROOT/output"
COMBINED_MD="$OUTPUT_DIR/joel-consolidated.md"
OUTPUT_PDF="$OUTPUT_DIR/joel-consolidated.pdf"
TEMPLATE="$PROJECT_ROOT/templates/pdf/joel.latex"

echo "=========================================="
echo "📖 Joel PDF (CONSOLIDATED 2026)"
echo "=========================================="
echo ""

if [ ! -f "$TEMPLATE" ]; then
    echo "ERROR: Template not found: $TEMPLATE"
    exit 1
fi

mkdir -p "$OUTPUT_DIR"

cat > "$COMBINED_MD" << 'HEADER'
---
title: "約珥書研讀"
subtitle: "Book of Joel Deep Study — 2026 整編版"
author: "PubHub 三書精讀系統"
date: "2026年10月"
publisher: "三書精讀出版系統"
copyright: |
  版權所有 © 2026 Soli Deo Gloria — 唯獨榮耀神

  **資源整合：**

  • **老弟兄查經方法論之應用**（倉庫中沒有老弟兄以約珥書為題的查經記錄，詳見附錄〈引用出處總表〉的誠實聲明）

  • **John Calvin** — *Commentaries on the Twelve Minor Prophets*, vol. 2（公有領域）

  • **Matthew Henry** — *Commentary on the Whole Bible*（公有領域）

  • **教父** — 屈梭多模、居普良、耶路撒冷的區利羅、特土良（newadvent.org，公有領域）

  • **G. Campbell Morgan** — 解經著作（公有領域）

  • **John MacArthur** — 論到約珥書的講道 (gty.org)；他沒有約珥書的逐節講道

  **雖然如此，一心歸向我**

  「耶和華說：雖然如此，你們應當禁食、哭泣、悲哀，一心歸向我。」（珥 2:12）

  **經文版權聲明 (Scripture Copyright Notices)**

  2026 年 10 月 · 初版。本版為教會內部贈閱版（非賣品）；公開發行時另行申請 ISBN。

  中文經文引自《聖經》和合本，屬公有領域；逐節核對來源見附錄〈引用出處總表〉。

  Scripture quotations taken from the New American Standard Bible® (NASB),
  Copyright © 1960, 1971, 1977, 1995 by The Lockman Foundation. Used by
  permission. All rights reserved. lockman.org
---

HEADER

chapter_count=0

# Strip the 7-line YAML front matter, convert ^n^ / ^24-25^ verse markers to
# \textsuperscript{}{} (the trailing {} keeps a digit from abutting a following
# \textbf{ — see build-2-peter-consolidated.sh for the root cause).
emit() {
    tail -n +8 "$1" | sed 's/\^\([0-9][0-9:-]*\)\^/\\textsuperscript{\1}{}/g'
}

# A numbered chapter (the five sections of Joel).
add_file() {
    local f="$1"
    [ -f "$f" ] || { echo "❌ Missing file: $1 — aborting build"; exit 1; }
    echo "  Adding: $(basename "$f")"
    emit "$f" >> "$COMBINED_MD"
    printf '\n\n\\newpage\n\n' >> "$COMBINED_MD"
    ((chapter_count++))
}

# Front/back matter: first H1 marked unnumbered so it does not consume a
# chapter number.
add_front() {
    local f="$1"
    [ -f "$f" ] || { echo "❌ Missing file: $1 — aborting build"; exit 1; }
    echo "  Adding (unnumbered): $(basename "$f")"
    emit "$f" \
      | awk 'BEGIN{done=0} /^# /{ if(!done){ sub(/[[:space:]]*$/,""); if($0 !~ /\{\.unnumbered\}$/) $0=$0" {.unnumbered}"; done=1 } } {print}' >> "$COMBINED_MD"
    printf '\n\n\\newpage\n\n' >> "$COMBINED_MD"
    ((chapter_count++))
}

# Part divider. $2 is the one-line description (carries 「啟示的次序·第N步」);
# optional $3-$5 add the 貫穿的線 / 鑰節 / 貫穿的問題 table.
# printf '%s' (not %b) on purpose: descriptions are plain text, and %b would
# turn a literal backslash sequence into a control character.
add_volume() {
    printf '# %s {.unnumbered}\n\n> %s\n' "$1" "$2" >> "$COMBINED_MD"
    if [ -n "$3" ]; then
        printf '\n| | |\n|---|---|\n| **貫穿的線** | %s |\n| **鑰節** | %s |\n| **貫穿的問題** | %s |\n' \
            "$3" "$4" "$5" >> "$COMBINED_MD"
    fi
    printf '\n\\newpage\n\n' >> "$COMBINED_MD"
    echo "  --- $1"
}

add_chapter() {
    local f
    for f in "$INPUT_DIR/$1-"*.md; do
        [ -f "$f" ] && { add_file "$f"; return 0; }
    done
    echo "❌ Missing chapter file for prefix '$1-' in $INPUT_DIR — aborting build"
    exit 1
}

# 前言
add_front "$INPUT_DIR/000-preface.md"

# ============================================================
# 卷首 · 定位
# ============================================================
add_volume "卷首 · 定位 (Orientation)" \
    "讀正文之前先讀這三章：地圖、座標、骨幹——啟示的次序與神的計劃。"
add_front "$INPUT_DIR/00-overview.md"
add_front "$INPUT_DIR/00a-joel-position.md"
add_front "$INPUT_DIR/00c-revelation-order.md"

# ============================================================
# 正文 · 五卷
# ============================================================
add_volume "卷一 · 話臨到 (The Word Came) · 1:1-20" \
    "啟示的次序·第一步：話先臨到，然後才有解釋。蝗災還沒有被說明，書的第一句是「耶和華的話臨到」（1:1）；百姓被吩咐的第一件事是聽、是告訴子孫（1:2-3），然後才哀號（1:5）、才禁食（1:14），並向祂呼求（1:19）。" \
    "**話在災之先**——先聽，再傳，後哀號" \
    "1:3「你們要將這事傳與子，子傳與孫，孫傳與後代」" \
    "我讀自己生命中的災，是先看見災，還是先聽見話？"
add_chapter 01
add_chapter 02
add_chapter 03

add_volume "卷二 · 耶和華的日子 (The Day of the LORD) · 2:1-11" \
    "啟示的次序·第二步：日子臨近，軍隊是祂的。吹角的是祂（2:1），在軍旅前發聲的也是祂（2:11）。毀滅者不在祂的轄制之外。" \
    "**日子是祂的日子**——「耶和華的日子」五次中的第二、第三次" \
    "2:11「耶和華在他軍旅前發聲，他的隊伍甚大」" \
    "我心裏有沒有一個「不在祂手裏」的角落？"
add_chapter 04

add_volume "卷三 · 歸向 (Return) · 2:12-17" \
    "啟示的次序·第三步：在審判還在行進的時候，祂先開口邀請。「雖然如此」（2:12）之後，才有「也未可知」（2:14）。邀請的根據，是祂自己的名號（2:13）。" \
    "**雖然如此**——審判之中的邀請" \
    "2:13「你們要撕裂心腸，不撕裂衣服」" \
    "我現在做的悔改，撕的是衣服，還是心腸？"
add_chapter 05

add_volume "卷四 · 回答與澆灌 (Answer and Outpouring) · 2:18-32" \
    "啟示的次序·第四步：祂回答，先補還，再澆灌。「耶和華就為自己的地發熱心」（2:18）；糧食回來，年歲被補還（2:25）；然後，「以後，我要將我的靈澆灌凡有血氣的」（2:28）。" \
    "**補還，然後澆灌**——先給地土，再給自己的靈" \
    "2:25「那些年所吃的，我要補還你們」；2:28「以後，我要將我的靈澆灌凡有血氣的」" \
    "我等候的，是祂補還我失去的，還是祂自己？"
add_chapter 06
add_chapter 07

add_volume "卷五 · 列國與錫安 (The Nations and Zion) · 3:1-21" \
    "啟示的次序·第五步，也是全書的終點：先復興祂的百姓（3:1），再審判列國（3:2），最後，全書最後一個詞組是「耶和華住在錫安」（3:21）。" \
    "**住在**——全書最後一個動詞（3:17；3:21）" \
    "3:17「你們就知道我是耶和華─你們的神，且又住在錫安─我的聖山」" \
    "我知道的，是祂的作為，還是祂自己？"
add_chapter 08
add_chapter 09
add_chapter 10

# ============================================================
# 卷末 · 全書領受總綱
# ============================================================
add_volume "卷末 · 回望 (Looking Back)" \
    "十章讀完，把全書的領受收攏成一張圖，再從約珥走到五旬節，走到啟示錄的水與日子——看見那位住在錫安的。"

# The study file is a synthesis OF the ten chapters, so it sits after them
# (as in Joel and Daniel), not in the front matter. No YAML: first line is its H1.
if [ -f "$STUDY_FILE" ]; then
    echo "  Adding: elder-wong-systematic-study.md (as 全書領受總綱)"
    printf '# 全書領受總綱——老弟兄查經法 (Systematic Reception) {.unnumbered}\n\n' >> "$COMBINED_MD"
    tail -n +2 "$STUDY_FILE" | sed 's/^#/##/' | sed 's/\^\([0-9][0-9:-]*\)\^/\\textsuperscript{\1}{}/g' >> "$COMBINED_MD"
    printf '\n\n\\newpage\n\n' >> "$COMBINED_MD"
    ((chapter_count++))
else
    echo "❌ Missing file: $STUDY_FILE — aborting build"
    exit 1
fi
add_front "$INPUT_DIR/99-to-pentecost-and-revelation.md"

# ============================================================
# 附錄
# ============================================================
add_volume "附錄 (Appendices)" \
    "經文與主題索引、讀經計劃、引用出處總表——供查閱、跨章對照，並如實交代每一處引句的查證方式。"
add_front "$INPUT_DIR/98-appendix-indices.md"
add_front "$INPUT_DIR/96-appendix-reading-plan.md"
add_front "$INPUT_DIR/99-appendix-references.md"

# 跋 — last content file: no trailing \newpage (the colophon opens its own page).
[ -f "$INPUT_DIR/999-afterword.md" ] || { echo "❌ Missing file: $INPUT_DIR/999-afterword.md — aborting build"; exit 1; }
echo "  Adding (unnumbered): 999-afterword.md"
emit "$INPUT_DIR/999-afterword.md" \
  | awk 'BEGIN{done=0} /^# /{ if(!done){ sub(/[[:space:]]*$/,""); if($0 !~ /\{\.unnumbered\}$/) $0=$0" {.unnumbered}"; done=1 } } {print}' >> "$COMBINED_MD"
((chapter_count++))

echo ""
echo "✅ Combined markdown: $COMBINED_MD ($(wc -l < "$COMBINED_MD") lines, $chapter_count sections)"
echo ""

# Wrap Greek runs in an explicit {\greekfont …} group passed through pandoc as
# raw LaTeX (see build-2-peter-consolidated.sh for why ucharclasses alone is
# not trusted with bold spans, and why the group must be a `…`{=latex} span —
# a bare {…} is escaped by pandoc into an unscoped font switch). Chapter
# markdown therefore carries plain Greek, never a hand-written wrap.
echo "Wrapping Greek Unicode runs in {\\greekfont ...}..."
COMBINED_MD_PATH="$COMBINED_MD" python3 <<'PYEOF'
import os, re
path = os.environ['COMBINED_MD_PATH']
text = open(path, encoding='utf-8').read()
# Skip anything already inside a backtick span.
parts = re.split(r'(`[^`]*`(?:\{=latex\})?)', text)
greek_run = re.compile(r'[Ͱ-Ͽἀ-῿]+(?: [Ͱ-Ͽἀ-῿]+)*')
n = 0
for i in range(0, len(parts), 2):
    def wrap(m):
        global n
        n += 1
        return '`{\\greekfont ' + m.group(0) + '}`{=latex}'
    parts[i] = greek_run.sub(wrap, parts[i])
open(path, 'w', encoding='utf-8').write(''.join(parts))
print(f"  Wrapped {n} Greek run(s)")
PYEOF

echo "🔨 Generating PDF with joel.latex template..."

# --verbose is load-bearing: without it pandoc swallows the xelatex log and
# every grep-the-log check (here and in driver.sh) passes vacuously.
source "$SCRIPT_DIR/lib/latex-check.sh"
LATEX_LOG="${OUTPUT_PDF%.pdf}-build.log"

pandoc "$COMBINED_MD" \
  -o "$OUTPUT_PDF" \
  --verbose \
  --pdf-engine=xelatex \
  --template="$TEMPLATE" \
  --from=markdown-superscript-subscript \
  --toc \
  --toc-depth=1 \
  --top-level-division=chapter > "$LATEX_LOG" 2>&1
PANDOC_EXIT=$?

latex_build_report "$PANDOC_EXIT" "$LATEX_LOG" "$OUTPUT_PDF" || exit 1
